// ZCL frame encoding differential for command options, manufacturer codes,
// reserved bits and custom clusters, against pinned zigbee-herdsman 11.2.0.
// Fixtures are generated by tools/oracle/generate-frame-options.mjs.

use serde::Deserialize;
use serde_json::{json, Value};
use zigbee_apiarist::zspec::zcl::definition::enums::DataType;
use zigbee_apiarist::zspec::zcl::utils::{Cluster, Command, CustomClusters, Parameter, Utils};
use zigbee_apiarist::zspec::zcl::zcl_frame::Frame;
use zigbee_apiarist::zspec::zcl::zcl_header::Header;

#[derive(Debug, Deserialize)]
struct Fixture {
    revision: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    cluster: String,
    command: String,
    #[serde(rename = "frameType")]
    frame_type: u8,
    direction: u8,
    #[serde(rename = "disableDefaultResponse")]
    disable_default_response: bool,
    #[serde(rename = "manufacturerCode")]
    manufacturer_code: Option<u16>,
    #[serde(rename = "transactionSequenceNumber")]
    transaction_sequence_number: u8,
    payload: Value,
    #[serde(rename = "reservedBits")]
    reserved_bits: u8,
    #[serde(rename = "customCluster")]
    custom_cluster: Option<CustomClusterFixture>,
    expected: String,
}

#[derive(Debug, Deserialize)]
struct CustomClusterFixture {
    name: String,
    #[serde(rename = "ID")]
    id: u32,
    #[serde(rename = "manufacturerCode")]
    manufacturer_code: Option<u16>,
    command: CustomCommandFixture,
}

#[derive(Debug, Deserialize)]
struct CustomCommandFixture {
    name: String,
    #[serde(rename = "ID")]
    id: u8,
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn custom_clusters(case: &Case) -> CustomClusters {
    let Some(spec) = &case.custom_cluster else {
        return CustomClusters::empty();
    };
    let mut cluster = Cluster::new(&spec.name, spec.id);
    cluster.manufacturerCode = spec.manufacturer_code;
    let mut command = Command::new(&spec.command.name, spec.command.id);
    command.parameters = vec![Parameter::new("value", DataType::UINT8)];
    command.order = 0;
    cluster.commands.insert(command.name.clone(), command);
    CustomClusters::from_clusters(vec![cluster])
}

#[test]
fn frame_options_match_pinned_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/frame-options-pinned.json")).expect("fixture");
    assert_eq!(fixture.revision, "zigbee-herdsman 11.2.0");
    assert_eq!(fixture.cases.len(), 10);
    for case in &fixture.cases {
        let custom = custom_clusters(case);
        let cluster = Utils::get_cluster(case.cluster.clone(), case.manufacturer_code, &custom);
        let command = if case.frame_type == 0 {
            Utils::get_global_command(case.command.as_str())
        } else if case.direction == 1 {
            Utils::get_cluster_command_response(&cluster, case.command.as_str())
        } else {
            Utils::get_cluster_command(&cluster, case.command.as_str())
        };
        let frame = Frame::create_with_definitions(
            cluster.clone(),
            command,
            case.frame_type,
            case.direction,
            case.disable_default_response,
            case.manufacturer_code,
            case.transaction_sequence_number,
            case.payload.clone(),
            case.reserved_bits,
        );
        let bytes = frame.to_buffer();
        assert_eq!(hex(&bytes), case.expected, "{}", case.name);
        // Decoding the upstream bytes must produce the same command and
        // re-encode identically.
        let header = Header::from_buffer(&bytes).expect("header");
        let cluster_id = cluster.ID as u16;
        let decoded = Frame::from_buffer(cluster_id, Some(header), &bytes, &custom);
        assert_eq!(decoded.command.name, case.command, "{}", case.name);
        assert_eq!(hex(&decoded.to_buffer()), case.expected, "{}", case.name);
    }
}

#[test]
fn endpoint_plans_preserve_options_and_manufacturer_codes() {
    // The dry-run transport builds frames through the real Endpoint helpers; a
    // regression there would silently change the wire format even though the
    // direct Frame differential still passes. This test pins the shared
    // construction path used by `Endpoint::command`.
    let cluster = Utils::get_cluster("genOnOff", None, &CustomClusters::empty());
    let command = Utils::get_cluster_command(&cluster, "on");
    let frame =
        Frame::create_with_definitions(cluster, command, 1, 0, false, None, 0x2a, json!({}), 0);
    assert_eq!(hex(&frame.to_buffer()), "012a01");
}
